TS=$(date +%s); G="Sprint-23 WIP1 concurrent research subject $TS"; for i in 1 2 3 4 5 6; do curl -sS -o /tmp/gate-s23-wip-$i.json -w "R${i}_HTTP=%{http_code}\n" --max-time 30 -X POST http://127.0.0.1:4111/api/missions -H 'Authorization: Bearer rn-gate-s23' -H 'Content-Type: application/json' -d "{\"templateKey\":\"research\",\"goal\":\"$G\",\"idempotencyKey\":\"wip-research-$i-$TS\",\"args\":{\"goal\":\"$G\"}}" & done; wait; echo; for i in 1 2 3 4 5 6; do echo "R${i}=$(tr -d '\n' < /tmp/gate-s23-wip-$i.json)"; done; OKC=0; WIPC=0; for i in 1 2 3 4 5 6; do grep -qE '"ok"[[:space:]]*:[[:space:]]*true' /tmp/gate-s23-wip-$i.json && OKC=$((OKC+1)); grep -qE '"code"[[:space:]]*:[[:space:]]*"WIP_ONE_EXCEEDED"' /tmp/gate-s23-wip-$i.json && WIPC=$((WIPC+1)); done; echo "OK_COUNT=$OKC WIP_BODY_COUNT=$WIPC"; P1=STEP2_PROOF=ok; P2=wip_body; if [ "$OKC" -ge 1 ] && [ "$WIPC" -ge 1 ]; then printf '%s+%s\n' "$P1" "$P2"; else N1=NO_WIP; N2=_IN_BURST; printf '%s%s\n' "$N1" "$N2"; fi
